-- req_id 를 직접 넣었으므로 IDENTITY 다음 번호를 현재 최댓값 뒤로 옮긴다
ALTER TABLE GRAD_REQ MODIFY req_id GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH LIMIT VALUE);
